SELECT distinct eis.id, eis.system_id AS systemId, eis.name, eis.code, eis.version, eis.desc AS description, eis.category_count AS categoryCount, eis.item_count AS itemCount, eis.object_type_id AS objectTypeId, eis.status_id AS statusId, eis.create_by AS createBy, eis.biz_create_time AS bizCreateTime, eis.biz_update_time AS bizUpdateTime,
sot.name AS objectTypeName, ss.name AS statusName, creator.user_name AS createByName
FROM eval_index_system eis
INNER JOIN ( SELECT DISTINCT system_id FROM ( SELECT DISTINCT system_id FROM eval_index_system WHERE deleted = 0 AND tenant_id = #{reqVO.tenantId}
AND name LIKE CONCAT('%', #{reqVO.name}, '%')
AND code = #{reqVO.code}
AND system_id = #{reqVO.systemId}
AND object_type_id = #{reqVO.objectTypeId}
AND status_id = #{reqVO.statusId}
AND version = #{reqVO.version}
) AS filtered_systems ) AS unique_systems ON eis.system_id = unique_systems.system_id
LEFT JOIN sys_object_type sot ON eis.object_type_id = sot.type_id
LEFT JOIN sys_status ss ON eis.status_id = ss.status_id LEFT JOIN sys_user creator ON eis.create_by = creator.user_id
WHERE eis.deleted = 0 AND eis.tenant_id = #{reqVO.tenantId}
ORDER BY eis.biz_create_time DESC

SELECT COUNT(DISTINCT system_id)
FROM eval_index_system
WHERE deleted = 0
AND tenant_id = #{reqVO.tenantId}



    AND name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND code = #{reqVO.code}


    AND system_id = #{reqVO.systemId}


    AND object_type_id = #{reqVO.objectTypeId}


    AND status_id = #{reqVO.statusId}


    AND version = #{reqVO.version}

SELECT system_id FROM eval_index_system
WHERE id = #{id}
  AND deleted = 0
